const prepare = function invoiceReminders({ values, timezone, signature, now }) {
  if (!Array.isArray(values)) throw new Error("Invoice values must be an array.");
  if (!values.length) return { reminders: [], count: 0 };
  const headers = values[0];
  const required = ["Numero", "Cliente", "Email", "Importo", "Scadenza", "Stato"];
  if (!Array.isArray(headers) || required.some((header) => !headers.includes(header)))
    throw new Error("Invoice sheet headers must include " + required.join(", ") + ".");
  for (const header of required)
    if (headers.filter((name) => name === header).length !== 1)
      throw new Error("Duplicate invoice header: " + header);
  const dateParts = new Intl.DateTimeFormat("en-GB", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now ? new Date(now) : new Date());
  const part = (name) => Number(dateParts.find((value) => value.type === name).value);
  const today = Date.UTC(part("year"), part("month") - 1, part("day"));
  const reminders = [];
  for (const [sourceIndex, row] of values.slice(1).entries()) {
    if (!Array.isArray(row)) throw new Error("Invoice row must be an array.");
    const invoice = Object.fromEntries(headers.map((header, index) => [header, row[index] ?? ""]));
    if (String(invoice.Stato).trim().toLowerCase() === "pagata") continue;
    const match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(String(invoice.Scadenza).trim());
    if (!match) continue;
    const [, day, month, year] = match.map(Number);
    const due = new Date(Date.UTC(year, month - 1, day));
    if (
      due.getUTCFullYear() !== year ||
      due.getUTCMonth() !== month - 1 ||
      due.getUTCDate() !== day
    )
      continue;
    const daysRemaining = Math.round((due.getTime() - today) / 86400000);
    if (daysRemaining > 3) continue;
    const to = String(invoice.Email).trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to))
      throw new Error("Invalid email for invoice " + invoice.Numero + ".");
    const overdue = daysRemaining < 0;
    const dueText = `${String(day).padStart(2, "0")}/${String(month).padStart(2, "0")}/${year}`;
    reminders.push({
      to,
      daysRemaining,
      sourceIndex,
      subject: `Promemoria: fattura ${invoice.Numero} ${overdue ? "scaduta" : "in scadenza"}`,
      body: `Gentile ${invoice.Cliente},\n\nle ricordiamo che la fattura n. ${invoice.Numero} di € ${invoice.Importo} ${overdue ? "risulta scaduta il" : "è in scadenza il"} ${dueText}.\n\nSe il pagamento è già stato effettuato, la preghiamo di ignorare questo messaggio.\n\nPer qualsiasi chiarimento siamo a disposizione.\n\nCordiali saluti,\n${signature}`,
    });
  }
  return { reminders, count: reminders.length };
};

const headers = ["Numero", "Cliente", "Email", "Importo", "Scadenza", "Stato"];
const items = $input.all();
const values = [headers, ...items.map((item) => headers.map((header) => item.json[header] ?? ""))];
return prepare({
  values,
  timezone: $now.zoneName,
  signature: "[LA TUA AZIENDA]",
  now: $now.toISO(),
}).reminders.map((reminder) => ({ json: reminder, pairedItem: { item: reminder.sourceIndex } }));
